import java.util.*;

class Solution {
    public int countReadings(String code) {
        int n = code.length();
        int prev2 = 1, prev1 = 1;                     // ways[i-2], ways[i-1]; ways[0] = 1
        if (n == 0) return 0;
        prev1 = code.charAt(0) == '0' ? 0 : 1;        // ways[1]
        for (int i = 2; i <= n; i++) {
            int cur = 0;
            if (code.charAt(i - 1) != '0') cur += prev1;              // single digit piece
            int two = (code.charAt(i - 2) - '0') * 10 + (code.charAt(i - 1) - '0');
            if (two >= 10 && two <= 26) cur += prev2;                  // two digit piece
            prev2 = prev1;
            prev1 = cur;
        }
        return prev1;
    }
}

