class Solution:
    def countReadings(self, code: str) -> int:
        prev2, prev = 1, 1
        for i in range(len(code)):
            cur = prev if code[i] != "0" else 0
            if i > 0 and 10 <= int(code[i - 1:i + 1]) <= 26: cur += prev2
            prev2, prev = prev, cur
        return prev

